messages.content:
Tool response:
Tool: create_reservation
Description: Create Reservation
Parameters:
    {
      "type": "object",
      "properties": {
        "team_name": {
          "type": "string",
          "title": "Team Name",
          "description": "Name of the team requesting the reservation"
        },
        "equipment_name": {
          "type": "string",
          "title": "Equipment Name",
          "description": "Name of the equipment being reserved"
        },
        "location_name": {
          "type": "string",
          "title": "Location Name",
          "description": "Name of the location where the equipment will be used"
        },
        "assigned_user_username": {
          "type": "string",
          "title": "Assigned User Username",
          "description": "Username of the user to whom the reservation is assigned"
        },
        "project_reference": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Project Reference",
          "description": "Reference code of the project associated with this reservation"
        },
        "start_time": {
          "type": "string",
          "title": "Start Time",
          "description": "Start datetime of the reservation in ISO format (YYYY-MM-DDTHH:MM:SS)"
        },
        "end_time": {
          "type": "string",
          "title": "End Time",
          "description": "End datetime of the reservation in ISO format (YYYY-MM-DDTHH:MM:SS)"
        }
      },
      "required": [
        "team_name",
        "equipment_name",
        "location_name",
        "assigned_user_username",
        "start_time",
        "end_time"
      ]
    }
